@Service
public class TransferFacade {          // bean riêng: gọi service ngoài TRƯỚC khi mở transaction
    public void transfer(long fromId, long toId, long amount) {
        limitClient.checkDailyLimit(fromId, amount);
        transferService.transfer(fromId, toId, amount);   // đi qua proxy nên @Transactional có tác dụng
    }
}

@Service
public class TransferService {

    @Transactional   // một transaction cho cả trừ và cộng
    public void transfer(long fromId, long toId, long amount) {
        // khoá hai ví theo thứ tự id tăng dần: hai lệnh chuyển ngược chiều cùng lúc sẽ không deadlock
        Map<Long, Wallet> locked = walletRepository.lockAllByIdOrdered(List.of(fromId, toId)).stream()
                .collect(Collectors.toMap(Wallet::getId, w -> w));
        Wallet from = locked.get(fromId);
        Wallet to = locked.get(toId);
        from.debit(amount);    // ném InsufficientBalanceException (unchecked) nếu không đủ
        to.credit(amount);
        // commit một lần khi method kết thúc; exception unchecked thì rollback cả hai
    }
}

